    /*
     * Get parqueo by parqueo_id
     */
    function get_parqueo($parqueo_id)
    {
        $parqueo = $this->db->query("
                SELECT 
                  p.*, t.producto_nombre
                FROM
                  parqueo p

                LEFT JOIN 
                producto t on t.producto_id = p.producto_id

                WHERE
                parqueo_id = ".$parqueo_id."
        ",array($parqueo_id))->row_array();

        return $parqueo;
    }
    
    /*
     * Get all parqueo count
     */
    function get_all_parqueo_count()
    {
        $parqueo = $this->db->query("
            SELECT
                count(*) as count

            FROM
                `registro_parqueo`
        ")->row_array();

        return $parqueo['count'];
    }
        
    /*
     * Get all parqueo
     */
    function get_all_parqueo($params = array())
    {
        $limit_condition = "";
        if(isset($params) && !empty($params))
            $limit_condition = " LIMIT " . $params['offset'] . "," . $params['limit'];
        
        $sql = "select * from registro_parqueo r, cliente c, estado e 
                where
                r.cliente_id = c.cliente_id and
                r.estado_id = e.estado_id and
                r.estado_id = 1";
        $parqueo = $this->db->query($sql)->result_array();

        return $parqueo;
    }
        
