    /*
     * parqueoes
     */
    function get_parqueoes()
    {
        $sql =  "select p.*
                from parqueo p 
                where 
                p.estado_id = 1 and 
                p.parqueo_id in 
                ( select  distinct(parqueo_id) from detalle_parqueo)";
        return $this->db->query($sql)->result_array(); 
